import * as fs from 'node:fs/promises';
import * as path from 'node:path';
import { gunzipSync } from 'node:zlib';
import { createHash } from 'node:crypto';
import { isDeepStrictEqual } from 'node:util';
import { pathToFileURL } from 'node:url';
import { spawnSync } from 'node:child_process';
const project = process.env.OCBI_PROJECT;
const work = process.env.OCBI_STUDY_ROOT;
const directory = path.join(project, 'benchmarks/results/self-curated-round2-2026-10-07');
const digest = bytes => createHash('sha256').update(bytes).digest('hex');
const packedBytes = await fs.readFile(path.join(directory, 'results-evidence.json.gz'));
const packed = JSON.parse(gunzipSync(packedBytes));
const prereg = JSON.parse(gunzipSync(await fs.readFile(path.join(directory, 'preregistration.json.gz'))));
const reportBytes = await fs.readFile(path.join(directory, 'report.json'));
const published = JSON.parse(reportBytes);
if (digest(reportBytes) !== packed.reportSha256) throw new Error('Public report hash mismatch');
const replay = await fs.mkdtemp(path.join(work, 'publication-replay-'));
const restore = text => text.replaceAll('${WORK}', replay).replaceAll('${PROJECT}', project).replaceAll('${USER_HOME}', path.join(replay, 'home'));
const files = new Map();
for (const file of [...prereg.files, ...packed.files]) {
  if (digest(Buffer.from(file.content)) !== file.normalizedSha256) throw new Error(`Embedded content hash mismatch: ${file.path}`);
  files.set(file.path, file);
  if (file.path.startsWith('run/')) {
    const target = path.join(replay, file.path);
    await fs.mkdir(path.dirname(target), { recursive: true });
    await fs.writeFile(target, restore(file.content));
  }
}
const load = file => import(pathToFileURL(path.join(project, file)).href);
const { loadCompetitiveRun, buildCompetitiveReport } = await load('scripts/competitive-report.ts');
const { scoreQuery } = await load('scripts/competitive-scoring.ts');
const { parseOcbiCitationPaths, parseCodeGraphPaths, parseCodebaseMemoryPaths, parseGrepaiPaths } = await load('scripts/competitive-adapters.ts');
const artifacts = await loadCompetitiveRun(path.join(replay, 'run'));
const run = JSON.parse(restore(files.get('run/run.json').content));
const rebuilt = buildCompetitiveReport(artifacts.rows, { expectedTasks: artifacts.expectedTasks, conditions: run.options.conditions, bootstrapSamples: 10000, seed: 202610072 });
if (!isDeepStrictEqual(rebuilt, published.primaryReport)) throw new Error('Published primary report does not reproduce');
let successful = 0, unsupported = 0, errors = 0, records = 0;
const source = path.join(replay, 'run/active-source');
for (const repository of run.sourceLock.repositories) {
  const archive = path.join(work, 'archives', `${repository.name}-${repository.revision}.tar`);
  if (digest(await fs.readFile(archive)) !== repository.archiveSha256) throw new Error(`Source archive hash mismatch: ${repository.name}`);
  await fs.rm(source, { recursive: true, force: true });
  await fs.mkdir(source, { recursive: true });
  const extraction = spawnSync('tar', ['-xf', archive, '-C', source], { encoding: 'utf8' });
  if (extraction.status !== 0) throw new Error(`Pinned archive extraction failed: ${extraction.stderr}`);
  const input = JSON.parse(restore(files.get(`run/${repository.name}/inputs.json`).content));
  const queries = new Map(input.dataset.queries.map(query => [query.id, query]));
  const manifest = JSON.parse(files.get(`source-manifests/${repository.name}.json`).content);
  const eligible = new Set(manifest.files.filter(file => file.lexicalEligible).map(file => file.path));
  for (const condition of run.options.conditions) {
    for (const repeat of [1, 2, 3]) {
      for (const query of queries.values()) {
        const key = `run/${repository.name}/${condition}/repeat-${repeat}/${query.id}.json`;
        const record = JSON.parse(restore(files.get(key).content));
        if (record.repeat !== repeat || record.condition !== condition || record.queryId !== query.id) throw new Error(`Record identity mismatch: ${key}`);
        if (!isDeepStrictEqual(scoreQuery(query, record.score.rankedPaths, record.score.status), record.score)) throw new Error(`Score mismatch: ${key}`);
        if (record.score.status === 'success') {
          let paths;
          if (condition.startsWith('ocbi-')) paths = parseOcbiCitationPaths(record.raw, source, 50);
          else if (condition === 'codegraph') paths = parseCodeGraphPaths(record.raw, source, 50);
          else if (condition === 'codebase-memory') paths = parseCodebaseMemoryPaths(record.raw, source, 50);
          else if (condition === 'grepai') paths = parseGrepaiPaths(record.raw, source, 50);
          else if (condition === 'literal-unindexed') paths = record.raw.stdout.split('\0').filter(Boolean).map(file => file.replace(/^\.\//, '')).filter(file => eligible.has(file)).sort().slice(0, 10);
          else paths = record.raw.candidates.slice(0, 10).map(candidate => candidate.path);
          if (!isDeepStrictEqual(paths, record.score.rankedPaths)) throw new Error(`Raw returned-path replay mismatch: ${key}`);
          successful++;
        } else if (record.score.status === 'unsupported') unsupported++;
        else errors++;
        records++;
      }
    }
  }
}
if (artifacts.rows.length !== 700 || records !== 2100 || successful + unsupported + errors !== 2100 || unsupported !== 138) throw new Error('Incomplete or changed execution matrix');
const observation = {
  schemaVersion: 1,
  kind: 'published-normalized-evidence-replay',
  independentReview: false,
  pinnedSourceArchivesRequiredForRawPathValidation: true,
  nativeIndexesRequiredForThisReplay: false,
  scoredRetrievalRequestsIssued: 0,
  preregistrationArchiveSha256: digest(await fs.readFile(path.join(directory, 'preregistration.json.gz'))),
  resultsEvidenceSha256: digest(packedBytes),
  reportSha256: digest(reportBytes),
  embeddedHashesVerified: prereg.files.length + packed.files.length,
  primaryRows: artifacts.rows.length,
  queryPassRecords: records,
  successfulRawPathReplays: successful,
  unsupportedPassRecords: unsupported,
  errorPassRecords: errors,
  primaryReportReproducedExactly: true,
  script: {
    originalSha256: digest(await fs.readFile(path.join(work, 'verify-publication.mjs'))),
    content: await fs.readFile(path.join(work, 'verify-publication.mjs'), 'utf8'),
  },
  interpretation: 'Replays normalized published execution evidence and rebuilds scoring/intervals using frozen existing helpers. Raw-path containment uses hash-verified pinned source archives. Does not independently rerun participant tools or establish representative, blind or SOTA claims.',
};
await fs.writeFile(path.join(directory, 'verification.json'), JSON.stringify(observation, null, 2) + '\n', { flag: 'wx' });
await fs.rm(replay, { recursive: true, force: true });
console.log(JSON.stringify({ ...observation, script: { originalSha256: observation.script.originalSha256 } }, null, 2));
